use kimo_core::{color::node_graph::{Graph,Node},commands::{Session,dispatch},effects::Frame};use serde_json::json;
fn node(id:&str,inputs:&[&str],kind:&str,fx:&str,value:f64)->Node{serde_json::from_value(json!({"id":id,"kind":kind,"inputs":inputs,"weights":inputs.iter().map(|_|json!({"base":1.})).collect::<Vec<_>>(),"effect":if kind=="grade"{json!({"id":id,"kind":fx,"params":{"stops":{"base":value}}})}else{json!(null)}})).unwrap()}
fn frame()->Frame{Frame{w:4,h:1,d:vec![0.1,0.2,0.3,1.,0.2,0.3,0.4,0.4,0.3,0.4,0.5,0.,-0.1,1.2,3.,1.]}}
#[test]fn serial_parity_diamond_cache_parallel(){let mut g=Graph::default();g.nodes.insert("a".into(),node("a",&["input"],"grade","exposure",1.));g.nodes.insert("b".into(),node("b",&["a"],"grade","exposure",1.));g.output="b".into();let mut f=frame();let mut expected=frame();for _ in 0..2{kimo_core::effects::apply("exposure",&g.nodes["a"].effect.as_ref().unwrap().params,&Default::default(),&mut expected,0.,0).unwrap();}g.apply(&mut f,0.,0,25.).unwrap();assert_eq!(f.d,expected.d);
g.nodes.insert("c".into(),node("c",&["a"],"grade","exposure",0.));g.nodes.insert("mix".into(),node("mix",&["b","c"],"parallel","",0.));g.output="mix".into();let mut f=frame();let st=g.apply(&mut f,0.,0,25.).unwrap();assert_eq!(st.evaluated_nodes,4);assert!(st.cache_hits>=1);let base=frame();for i in 0..f.d.len(){if i%4==3{assert_eq!(f.d[i],base.d[i])}else{assert!((f.d[i]-base.d[i]*3.).abs()<1e-6)}}let mut repeat=frame();g.apply(&mut repeat,0.,0,25.).unwrap();assert_eq!(f.d,repeat.d);}
#[test]fn layer_weights_mask_and_time(){let mut g=Graph::default();g.nodes.insert("a".into(),node("a",&["input"],"grade","exposure",1.));let mut n=node("mix",&["input","a"],"layer","",0.);n.weights[1]=kimo_core::keyframe::Prop::new(0.25);g.nodes.insert("mix".into(),n);g.output="mix".into();let mut f=frame();g.apply(&mut f,0.,0,25.).unwrap();assert!((f.d[0]-0.125).abs()<1e-7);let m=kimo_core::masks::new_layer("m".into(),"linear");g.nodes.get_mut("a").unwrap().mask=Some(m);let mut f=frame();g.apply(&mut f,0.,0,25.).unwrap();assert!(f.d[0]<f.d[8]);}
fn session()->(Session,serde_json::Value){let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":32,"height":32})).unwrap();let t=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":t,"source_type":"solid","color":[0.2,0.3,0.4],"start":0,"duration":1})).unwrap()["clip_id"].clone();(s,c)}
#[test]fn tools_cycle_rollback_roundtrip_tracking(){let(mut s,c)=session();dispatch(&mut s,"add_node",&json!({"clip_id":c,"node_id":"a","kind":"grade","effect_kind":"exposure","params":{"stops":1}})).unwrap();dispatch(&mut s,"add_node",&json!({"clip_id":c,"node_id":"b","parent":"a","kind":"grade","effect_kind":"exposure"})).unwrap();let before=serde_json::to_value(&s.project).unwrap();assert!(dispatch(&mut s,"connect_nodes",&json!({"clip_id":c,"node_id":"a","source":"b","slot":0})).is_err());assert_eq!(before,serde_json::to_value(&s.project).unwrap());dispatch(&mut s,"set_grade_output",&json!({"clip_id":c,"node_id":"b"})).unwrap();let m=kimo_core::masks::new_layer("m".into(),"ellipse");dispatch(&mut s,"set_node_mask",&json!({"clip_id":c,"node_id":"a","mask":m})).unwrap();dispatch(&mut s,"grade_node_tracking",&json!({"clip_id":c,"node_id":"a","samples":[{"time":0,"cx":0.2,"cy":0.5},{"time":1,"cx":0.8,"cy":0.5}]})).unwrap();let prop=json!({"base":0,"keys":[{"t":0,"v":0},{"t":1,"v":1}],"expr":[]});dispatch(&mut s,"set_node_param",&json!({"clip_id":c,"node_id":"b","parameter":"stops","property":prop})).unwrap();let i=dispatch(&mut s,"inspect_grade_graph",&json!({"clip_id":c})).unwrap();assert_eq!(i["order"],json!(["a","b"]));assert_eq!(i["graph"]["nodes"]["a"]["mask"]["props"]["cx"]["keys"][1]["v"],0.8);let bytes=serde_json::to_vec(&s.project).unwrap();let p:kimo_core::model::Project=serde_json::from_slice(&bytes).unwrap();assert_eq!(serde_json::to_value(p).unwrap()["tracks"],serde_json::to_value(&s.project).unwrap()["tracks"]);}
#[test]fn rendered_graph_and_no_graph_identity(){let(mut s,c)=session();let cache=kimo_core::render::Cache::new();let original=kimo_core::render::render_frame(&s.project,0.,&cache).unwrap();dispatch(&mut s,"add_node",&json!({"clip_id":c,"node_id":"a","kind":"grade","effect_kind":"exposure","params":{"stops":1}})).unwrap();let parked=kimo_core::render::render_frame(&s.project,0.,&cache).unwrap();assert_eq!(original.d,parked.d);dispatch(&mut s,"set_grade_output",&json!({"clip_id":c,"node_id":"a"})).unwrap();let after=kimo_core::render::render_frame(&s.project,0.,&cache).unwrap();assert!((after.d[0]-original.d[0]*2.).abs()<1e-7);dispatch(&mut s,"set_grade_graph",&json!({"clip_id":c,"graph":null})).unwrap();assert_eq!(original.d,kimo_core::render::render_frame(&s.project,0.,&cache).unwrap().d);}
#[test]fn budget_fail_closed_and_incomplete(){let mut g=Graph::default();g.nodes.insert("a".into(),node("a",&["input"],"grade","exposure",1.));g.output="a".into();g.cache_budget_mb=1;let mut f=Frame::new(512,512);let before=f.d.clone();assert!(g.apply(&mut f,0.,0,25.).unwrap_err().contains("budget"));assert_eq!(before,f.d);g.nodes.get_mut("a").unwrap().inputs.clear();g.nodes.get_mut("a").unwrap().weights.clear();assert!(g.apply(&mut frame(),0.,0,25.).unwrap_err().contains("incomplete"));}
#[test]fn masks_keyframes_bypass_and_reorder(){let mut g=Graph::default();let mut n=node("a",&["input"],"grade","exposure",1.);let mut mask=kimo_core::masks::new_layer("m".into(),"luma");for(k,v)in[("lo",0.15),("hi",0.35),("soft",0.)]{mask.props.insert(k.into(),kimo_core::keyframe::Prop::new(v));}n.mask=Some(mask);g.nodes.insert("a".into(),n);g.output="a".into();let mut f=frame();g.apply(&mut f,0.,0,25.).unwrap();assert!(f.d[0]>0.1);assert_eq!(f.d[12],-0.1);g.nodes.get_mut("a").unwrap().bypass=true;let mut f=frame();g.apply(&mut f,0.,0,25.).unwrap();assert_eq!(f.d,frame().d);g.nodes.get_mut("a").unwrap().bypass=false;g.nodes.get_mut("a").unwrap().mask=None;let p=&mut g.nodes.get_mut("a").unwrap().effect.as_mut().unwrap().params.get_mut("stops").unwrap();p.set_key(0.,0.,kimo_core::keyframe::Ease::Linear);p.set_key(1.,1.,kimo_core::keyframe::Ease::Linear);let mut f=frame();g.apply(&mut f,0.,0,25.).unwrap();assert_eq!(f.d,frame().d);g.apply(&mut f,1.,0,25.).unwrap();assert_eq!(f.d[0],0.2);}
#[cfg(feature="native-ocio")]
#[test]fn native_node_matches_explicit_processor(){use kimo_core::color::ocio_config::Config;let path=concat!(env!("CARGO_MANIFEST_DIR"),"/tests/data/minimal_aces.ocio");let mut g=Graph::default();let mut n=node("a",&["input"],"grade","film_soft_shoulder",0.);let e=n.effect.as_mut().unwrap();e.params.clear();for(k,v)in[("ocio_domain","display-referred"),("ocio_config",path),("ocio_working_space","ACEScg"),("ocio_linear_space","ACEScg"),("ocio_display_space","DisplayGamma2")]{e.strings.insert(k.into(),v.into());}g.nodes.insert("a".into(),n);g.output="a".into();let mut f=frame();f.d.iter_mut().for_each(|v|*v=v.max(0.));let mut r=Frame{w:f.w,h:f.h,d:f.d.clone()};let c=Config::from_file(path).unwrap();c.processor("ACEScg","DisplayGamma2").unwrap().apply(&mut r).unwrap();kimo_core::color::film_response::apply("film_soft_shoulder",&Default::default(),&mut r,0.,42).unwrap();c.processor("DisplayGamma2","ACEScg").unwrap().apply(&mut r).unwrap();g.apply(&mut f,0.,42,25.).unwrap();assert_eq!(f.d,r.d);}
#[test]fn real_graph_parity_proof(){if !std::path::Path::new("/tmp/subject-source.png").exists(){return}let(mut s,c)=session();s.project.width=640;s.project.height=360;s.project.tracks.clear();let a=dispatch(&mut s,"import_media",&json!({"path":"/tmp/subject-source.png"})).unwrap()["asset_id"].clone();let t=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":t,"source_type":"media","asset_id":a,"start":0,"duration":0.08})).unwrap()["clip_id"].clone();let mut cache=kimo_core::render::Cache::new();kimo_core::render::prepare_at(&s.project,&mut cache,Some(0.)).unwrap();let raw=kimo_core::render::render_frame(&s.project,0.,&cache).unwrap();std::fs::write("/tmp/node-real-before.f32",raw.d.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>()).unwrap();for (id,parent,stops)in[("a","input",0.5),("b","a",-0.25)]{dispatch(&mut s,"add_node",&json!({"clip_id":c,"node_id":id,"parent":parent,"kind":"grade","effect_kind":"exposure","params":{"stops":stops}})).unwrap();}dispatch(&mut s,"set_grade_output",&json!({"clip_id":c,"node_id":"b"})).unwrap();let after=kimo_core::render::render_frame(&s.project,0.,&cache).unwrap();let mut reference=Frame{w:raw.w,h:raw.h,d:raw.d.clone()};for stops in [0.5,-0.25]{let mut p=kimo_core::effects::Params::new();p.insert("stops".into(),kimo_core::keyframe::Prop::new(stops));kimo_core::effects::apply("exposure",&p,&Default::default(),&mut reference,0.,0).unwrap();}assert_eq!(after.d,reference.d);assert_eq!(after.d,kimo_core::render::render_frame(&s.project,0.,&cache).unwrap().d);std::fs::write("/tmp/node-real-after.f32",after.d.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>()).unwrap();let v=dispatch(&mut s,"evaluate_grade_graph_samples",&json!({"clip_id":c,"rgba":[0.2,0.3,0.4,1.]})).unwrap();assert_eq!(v["cache"]["evaluated_nodes"],2);}
#[test]fn all_edit_tools_and_mixer_weight_animation(){let(mut s,c)=session();for(id,stops)in[("a",0.),("b",1.)]{dispatch(&mut s,"add_node",&json!({"clip_id":c,"node_id":id,"kind":"grade","effect_kind":"exposure","params":{"stops":stops}})).unwrap();}dispatch(&mut s,"add_node",&json!({"clip_id":c,"node_id":"m","kind":"parallel"})).unwrap();for(i,src)in["a","b"].iter().enumerate(){dispatch(&mut s,"connect_nodes",&json!({"clip_id":c,"node_id":"m","source":src,"slot":i})).unwrap();}dispatch(&mut s,"set_grade_output",&json!({"clip_id":c,"node_id":"m"})).unwrap();let mut n=dispatch(&mut s,"inspect_grade_graph",&json!({"clip_id":c})).unwrap()["graph"]["nodes"]["m"].clone();n["weights"][1]=json!({"base":0,"keys":[{"t":0,"v":0},{"t":1,"v":1}]});dispatch(&mut s,"set_grade_node",&json!({"clip_id":c,"node":n})).unwrap();let eval=|s:&mut Session,t|dispatch(s,"evaluate_grade_graph_samples",&json!({"clip_id":c,"rgba":[0.2,0.3,0.4,1.],"time":t})).unwrap();assert!((eval(&mut s,0.)["rgba"][0].as_f64().unwrap()-0.2).abs()<1e-7);assert!((eval(&mut s,1.)["rgba"][0].as_f64().unwrap()-0.3).abs()<1e-7);assert!(dispatch(&mut s,"remove_grade_node",&json!({"clip_id":c,"node_id":"b"})).is_err());dispatch(&mut s,"set_grade_output",&json!({"clip_id":c,"node_id":"input"})).unwrap();dispatch(&mut s,"disconnect_nodes",&json!({"clip_id":c,"node_id":"m","slot":1})).unwrap();dispatch(&mut s,"remove_grade_node",&json!({"clip_id":c,"node_id":"b"})).unwrap();let v=dispatch(&mut s,"inspect_grade_graph",&json!({"clip_id":c})).unwrap();dispatch(&mut s,"set_grade_graph",&json!({"clip_id":c,"graph":v["graph"]})).unwrap();}
#[test]fn effect_error_transactional_and_stale_binding(){let mut g=Graph::default();let mut n=node("a",&["input"],"grade","luminance_shoulder",0.);n.effect.as_mut().unwrap().params.insert("peak".into(),kimo_core::keyframe::Prop::new(0.));g.nodes.insert("a".into(),n);g.output="a".into();let mut f=frame();let original=f.d.clone();assert!(g.apply(&mut f,0.,0,25.).is_err());assert_eq!(f.d,original);let e=g.nodes.get_mut("a").unwrap().effect.as_mut().unwrap();e.strings.insert("bound_linear_gamut".into(),"3".into());e.params.insert("gamut".into(),kimo_core::keyframe::Prop::new(3.));assert!(g.validate_project(&kimo_core::model::Project::default()).is_err());}
